    "H_555b65960dfef14ae49a15e7": {
      "type": "object",
      "required": [
        "zip",
        "country_code",
        "name",
        "phone"
      ],
      "description": "The information about the fulfillment service location.",
      "properties": {
        "address1": {
          "type": "string",
          "description": "The first line of the location. This typically includes information such as the street address or a post office box number.",
          "maxLength": 262144
        },
        "address2": {
          "type": "string",
          "description": "The second line of the location. This typically includes information such as an apartment, suite, or unit number.",
          "maxLength": 262144
        },
        "city": {
          "type": "string",
          "description": "The city.",
          "maxLength": 262144
        },
        "city_code": {
          "type": "string",
          "description": "The code for the city.",
          "maxLength": 262144
        },
        "country": {
          "type": "string",
          "description": "The country or region.",
          "maxLength": 262144
        },
        "country_code": {
          "type": "string",
          "description": "A two-letter country or region code that follows the [ISO 3166-1 (alpha 2)](https://www.iso.org/glossary-for-iso-3166.html) standard. ",
          "maxLength": 262144
        },
        "inventory_management": {
          "type": "boolean",
          "description": "Whether the product inventory for the location is managed by the fulfillment app.\n- `true`: Managed by the fulfillment app. \n- `false`: Managed by the SHOPLINE Admin.\n\nDefault value: `true`"
        },
        "name": {
          "type": "string",
          "description": "The location's name.",
          "maxLength": 262144
        },
        "permits_sku_sharing": {
          "type": "boolean",
          "description": "Whether the product inventory for the location is shared by other locations.\n- `true`: The product inventory for the location is shared by other locations.\n- `false`: The product inventory for the location is not shared by other locations.\n\nDefault value: `false`"
        },
        "phone": {
          "type": "string",
          "description": "The merchant's phone number.",
          "maxLength": 262144
        },
        "phone_code": {
          "type": "string",
          "description": "The international dialing code for the phone number.",
          "maxLength": 262144
        },
        "province": {
          "type": "string",
          "description": "The state or province.",
          "maxLength": 262144
        },
        "province_code": {
          "type": "string",
          "description": "The code for the state or province.",
          "maxLength": 262144
        },
        "zip": {
          "type": "string",
          "description": "The postal code of the location.",
          "maxLength": 262144
        }
      },
      "additionalProperties": false
    },
    "H_94cfdb7df9f4eba2f9e91254": {
      "type": "object",
      "description": "Fulfillment information.",
      "properties": {
        "tracking_info_list": {
          "type": "array",
          "description": "A list of tracking information. If this parameter is specified, the individual parameters `tracking_url`, `tracking_number`, and `tracking_company` will be ignored.\n\nMaximum size: 10",
          "items": {
            "type": "object",
            "properties": {
              "tracking_company": {
                "type": "string",
                "description": "Logistics service provider. Refer to [Logistics company list](https://developer.shopline.com/docs/apps/api-instructions-for-use/references/logistics-company-list) for valid values. ",
                "maxLength": 262144
              },
              "tracking_number": {
                "type": "string",
                "description": "The delivery tracking number provided by the logistics service provider.",
                "maxLength": 262144
              },
              "tracking_url": {
                "type": "string",
                "description": "The domain name of the logistics company.",
                "maxLength": 262144
              }
            },
            "additionalProperties": false
          },
          "maxItems": 10
        },
        "tracking_number": {
          "type": "string",
          "description": "The delivery tracking number provided by the logistics service provider.\n:::danger \t\n**DEPRECATED**:\nThis parameter is deprecated from API version v20250601. Refer to `tracking_info_list`. \n:::",
          "maxLength": 262144
        },
        "tracking_url": {
          "type": "string",
          "description": "The domain name of the logistics company.\n:::danger \t\n**DEPRECATED**：This parameter is deprecated from API version v20250601. Refer to `tracking_info_list`. \n:::",
          "maxLength": 262144
        },
        "line_items": {
          "type": "array",
          "description": "A list of order product snapshots.\n\nMaximum size: unlimited",
          "items": {
            "type": "object",
            "required": [
              "quantity",
              "id"
            ],
            "properties": {
              "id": {
                "type": "integer",
                "description": "The ID of the line item snapshot table, generated by the system. Combined with the order ID, it uniquely identifies a line item.",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              },
              "quantity": {
                "type": "integer",
                "description": "The quantity of products to be shipped.",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              }
            },
            "additionalProperties": false
          },
          "maxItems": 10
        },
        "notify_customer": {
          "type": "boolean",
          "description": "Indicates whether to notify the customer when creating or updating a fulfillment. \n- `true`: Notify the customer by email. \n- `false`: Do not notify the customer. \n\nDefault value: `false`"
        },
        "tracking_company": {
          "type": "string",
          "description": "Logistics service provider.\n:::danger\n**DEPRECATED**:\nThis parameter is deprecated from API version v20250601. Refer to `tracking_info_list`.\n:::\n",
          "maxLength": 262144
        }
      },
      "additionalProperties": false
    },
