    "H_e850b68a8ad5a297609bb158": {
      "type": "object",
      "description": "Email marketing subscription information.",
      "properties": {
        "consent_collected_from": {
          "type": "string",
          "description": "Subscription information source.\n\nMaximum length: 50",
          "maxLength": 262144
        },
        "consent_updated_at": {
          "type": "string",
          "description": "The date and time when the subscription was updated. Format: [ISO 8601](https://www.iso.org/iso-8601-date-and-time-format.html). \n\nExample: `2024-08-31T02:20:26+08:00` ",
          "maxLength": 262144
        },
        "opt_in_level": {
          "type": "integer",
          "description": "Subscription method. Valid values are:\n* `0` : unknown\n* `1` : single opt-in\n* `2` : confirmed opt-in\n\nThe default value depends on whether the **Marketing options** setting is enabled in the SHOPLINE Admin. \n\n* Enabled: Default value is `2`.\n* Disabled: Default value is `1`.",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991
        },
        "state": {
          "type": "integer",
          "description": "Email subscription status. Valid values are: \n\n* `0` : Unsubscribed\n* `1` : Subscribed\n* `2` : Not subscribed\n* `3` : Awaiting confirmation\n\nThis field must be passed when any other subfields under `email_marketing_consent` have values.",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991
        }
      },
      "additionalProperties": false
    },
