    "H_ac1c9b9deec2a47ab17fb55b": {
      "type": "object",
      "required": [
        "starts_at",
        "title"
      ],
      "properties": {
        "promotion_restrictions_type": {
          "type": "integer",
          "description": "The purchase limit type. Required when `has_promotion_restrictions` is `true`. Valid values are:\n- `1`: Activity-level. Limits the total purchase quantity per buyer across the entire activity, regardless of the products.\n- `2`: SKU-level. Limits the purchase quantity per buyer for a specific SKU.\n- `3`: Product-level. Limits the purchase quantity per buyer for a specific product (including all of its SKUs).",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991
        },
        "sale_channels": {
          "type": "array",
          "description": "A list of applicable sales channel handles for the activity. Required when `applies_to_all_channels` is `false`. You can obtain available sales channel handles via the [Query store information](https://developer.shopline.com/docs/admin-rest-api/store/query-store-information)  API.   \nMaximum size: 100",
          "items": {
            "type": "string",
            "maxLength": 262144
          },
          "maxItems": 10
        },
        "starts_at": {
          "type": "string",
          "description": "The date and time when the activity starts. Format: [ISO 8601](https://www.iso.org/iso-8601-date-and-time-format.html).",
          "maxLength": 262144
        },
        "title": {
          "type": "string",
          "description": "The activity title displayed in the SHOPLINE Admin.  \nMaximum length: 255",
          "maxLength": 262144
        },
        "applies_to_all_channels": {
          "type": "boolean",
          "description": "Whether the activity applies to all sales channels.\n- `true`: Applies to all sales channels.\n- `false`: Only applies to specified sales channels, which are determined by `sales_channels`.  \n\nDefault value: `true`"
        },
        "combined_with_discounts": {
          "type": "boolean",
          "description": "Whether the activity can be combined with other discounts.\n- `true`: Combinable\n- `false`: Not combinable  \n\nDefault value: `false`"
        },
        "ends_at": {
          "type": "string",
          "description": "The date and time when the activity ends. Required when `has_ends_at` is `true`, and must be later than `starts_at`. Format: [ISO 8601](https://www.iso.org/iso-8601-date-and-time-format.html).",
          "maxLength": 262144
        },
        "oversold_allow": {
          "type": "boolean",
          "description": "Whether to allow overselling.\n- `true`: Allow\n- `false`: Not allow  \n\nDefault value: `false`"
        },
        "promotion_restrictions_quantity": {
          "type": "integer",
          "description": "The purchase limit quantity. Required when `has_promotion_restrictions` is `true`. The specific tracking dimension for this limit is determined by `promotion_restrictions_type`.  \nValue range: 1-2147483647",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991
        },
        "sale_markets": {
          "type": "array",
          "description": "A list of applicable market IDs for the activity. Required when `applies_to_all_markets` is `false`. You can obtain available market IDs via the [Query market list](https://developer.shopline.com/docs/admin-rest-api/market/query-market-list) API.  \nMaximum size: 100",
          "items": {
            "type": "string",
            "maxLength": 262144
          },
          "maxItems": 10
        },
        "applies_to_all_markets": {
          "type": "boolean",
          "description": "Whether the activity applies to all markets.\n- `true`: Applies to all markets.\n- `false`: Only applies to specified markets, which are determined by `sales_markets`.  \n\nDefault value: `true`"
        },
        "has_ends_at": {
          "type": "boolean",
          "description": "Whether there is an end time for the activity.\n- `true`: There is an end time, determined by `ends_at`.\n- `false`: The activity is permanently valid.  \n\nDefault value: `false`"
        },
        "has_promotion_restrictions": {
          "type": "boolean",
          "description": "Whether to enable the purchase limit.\n- `true`: Enable\n- `false`: Disable  \n\nDefault value: `false`"
        }
      },
      "additionalProperties": false
    },
